from fractions import Fraction

def calculate_b_squared(a_val):
    # Constraint: a != 2
    if a_val == 2:
        return None

    # b^2 = a^2 - a / (a - 2)
    a_sq = a_val**2
    term2 = a_val / (a_val - 2)
    b_sq = a_sq - term2
    return b_sq

def is_perfect_rational_square(r):
    # r is assumed to be a rational number.
    if r < 0:
        return False

    # Convert to Fraction to work with exact arithmetic
    r_frac = Fraction(r).limit_denominator()

    # Check if numerator and denominator are perfect squares
    num = r_frac.numerator
    den = r_frac.denominator

    def is_square(n):
        if n < 0:
            return False
        s = int(n**0.5)
        return s*s == n

    return is_square(num) and is_square(den)

test_values = [0, 1, 3, -1]
results = {}

for a in test_values:
    b_sq = calculate_b_squared(a)

    if b_sq is not None:
        # Convert to Fraction for accurate checking
        b_sq_frac = Fraction(b_sq).limit_denominator()

        is_sq = is_perfect_rational_square(b_sq_frac)

        results[a] = {
            "b_squared": b_sq_frac,
            "is_square": is_sq
        }

print(results)

